/**
 * Unit tests for TextBuffer.expandCurrentSegment().
 * Note: The original code provided contains a bug: (len >> -1) is not a valid way to calculate 50%.
 * In Java, (len >> -1) is equivalent to (len >> 31), which is 0 or -1.
 * However, I will write tests based on the logic provided in the snippet.
 */
public class TextBuffer_expandCurrentSegment_TriageGen0Test {

    private TextBuffer textBuffer;
    private BufferRecycler recycler;

    // Accessing private field _currentSegment via reflection to setup state
    private static final String CURRENT_SEGMENT_FIELD = "_currentSegment";
    private static final String MAX_SEGMENT_LEN_FIELD = "MAX_SEGMENT_LEN";

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    /**
     * Helper to inject a specific char array into the private _currentSegment field
     * to control the growth logic.
     */
    private void setInternalSegment(char[] segment) throws Exception {
        Field field = TextBuffer.class.getDeclaredField(CURRENT_SEGMENT_FIELD);
        field.setAccessible(true);
        field.set(textBuffer, segment);
    }

    /**
     * Helper to get the MAX_SEGMENT_LEN value via reflection.
     */
    private int getMaxSegmentLen() throws Exception {
        Field field = TextBuffer.class.getDeclaredField(MAX_SEGMENT_LEN_FIELD);
        field.setAccessible(true);
        return (int) field.get(null);
    }

    @Test
    public void testExpandCurrentSegment_SmallBuffer() throws Exception {
        // Setup: segment of size 10
        char[] initial = new char[10];
        setInternalSegment(initial);

        // Calculation in code: 
        // len = 10
        // newLen = 10 + (10 >> -1) -> 10 >> -1 is 10 >> 31 = 0. So newLen = 10.
        // Since 10 is likely < MAX_SEGMENT_LEN, it returns copy of size 10.

        char[] expanded = textBuffer.expandCurrentSegment();

        Assert.assertNotNull(expanded);
        // Based on the provided logic (len >> -1), newLen becomes len + 0
        Assert.assertEquals(10, expanded.length);
        Assert.assertNotSame(initial, expanded); // Should be a copy
    }






}

